DSA.PY_SETUP = "PRELUDE_SRC = '# Preloaded before every program in DSA Atlas (in the browser and in tests).\\n# It mirrors what LeetCode gives you: typing names, common imports, and the\\n# ListNode / TreeNode classes, plus helpers to build and print them.\\nfrom typing import List, Optional, Dict, Tuple, Set\\nfrom collections import deque, defaultdict, Counter, OrderedDict\\nimport heapq, bisect, math, random, itertools, functools, string, re\\nfrom heapq import heappush, heappop, heapify, heappushpop, heapreplace, nlargest, nsmallest\\nfrom bisect import bisect_left, bisect_right, insort\\nfrom functools import lru_cache, cache, reduce\\nfrom math import inf, gcd\\n\\n\\nclass ListNode:\\n    def __init__(self, val=0, next=None):\\n        self.val = val\\n        self.next = next\\n\\n    def __repr__(self):\\n        return f\"ListNode({self.val})\"\\n\\n\\nclass TreeNode:\\n    def __init__(self, val=0, left=None, right=None):\\n        self.val = val\\n        self.left = left\\n        self.right = right\\n\\n    def __repr__(self):\\n        return f\"TreeNode({self.val})\"\\n\\n\\ndef build_list(vals):\\n    \"\"\"[1, 2, 3] -> 1 -> 2 -> 3 (returns the head node).\"\"\"\\n    dummy = ListNode()\\n    cur = dummy\\n    for v in vals:\\n        cur.next = ListNode(v)\\n        cur = cur.next\\n    return dummy.next\\n\\n\\ndef list_vals(head, limit=1000):\\n    \"\"\"Head node -> plain Python list (stops after `limit` nodes, so cycles are safe).\"\"\"\\n    out = []\\n    while head is not None and len(out) < limit:\\n        out.append(head.val)\\n        head = head.next\\n    return out\\n\\n\\ndef build_tree(vals):\\n    \"\"\"Level-order list like LeetCode\\'s [3, 9, 20, None, None, 15, 7] -> root TreeNode.\"\"\"\\n    if not vals or vals[0] is None:\\n        return None\\n    it = iter(vals)\\n    root = TreeNode(next(it))\\n    q = deque([root])\\n    while q:\\n        node = q.popleft()\\n        try:\\n            left = next(it)\\n        except StopIteration:\\n            break\\n        if left is not None:\\n            node.left = TreeNode(left)\\n            q.append(node.left)\\n        try:\\n            right = next(it)\\n        except StopIteration:\\n            break\\n        if right is not None:\\n            node.right = TreeNode(right)\\n            q.append(node.right)\\n    return root\\n\\n\\ndef tree_vals(root):\\n    \"\"\"Root TreeNode -> level-order list with None gaps (LeetCode\\'s format).\"\"\"\\n    if root is None:\\n        return []\\n    out, q = [], deque([root])\\n    while q:\\n        node = q.popleft()\\n        if node is None:\\n            out.append(None)\\n            continue\\n        out.append(node.val)\\n        q.append(node.left)\\n        q.append(node.right)\\n    while out and out[-1] is None:\\n        out.pop()\\n    return out\\n\\n\\ndef find_node(root, val):\\n    \"\"\"Return the first TreeNode with this value (used to pass nodes as arguments).\"\"\"\\n    q = deque([root])\\n    while q:\\n        node = q.popleft()\\n        if node is None:\\n            continue\\n        if node.val == val:\\n            return node\\n        q.append(node.left)\\n        q.append(node.right)\\n    return None\\n\\n\\ndef show(x):\\n    \"\"\"Convert results into plain values for printing and comparing.\"\"\"\\n    if isinstance(x, ListNode):\\n        return list_vals(x)\\n    if isinstance(x, TreeNode):\\n        return tree_vals(x)\\n    if isinstance(x, list):\\n        return [show(v) for v in x]\\n    if isinstance(x, tuple):\\n        return tuple(show(v) for v in x)\\n    return x\\n'\n# DSA Atlas Python runner + line-by-line tracer.\n# Runs inside Pyodide (browser) and inside tools/build.py (tests), so both\n# use exactly the same rules. Expects PRELUDE_SRC to be defined first.\nimport sys, io, json, time, ast, builtins, types, math\nfrom collections import deque as _deque\n\n_CO_OPTIMIZED = 1\n_SKIP = (types.ModuleType, type)\n_PRELUDE_CODE = compile(PRELUDE_SRC, '<prelude>', 'exec')  # noqa: F821 (defined by the loader)\n\n\nclass _StepLimit(BaseException):\n    \"\"\"Raised when the tracer records too many steps (BaseException so `except Exception` can't swallow it).\"\"\"\n\n\ndef _short(v, n=80):\n    try:\n        s = repr(v)\n    except Exception:\n        s = '<' + type(v).__name__ + '>'\n    return s if len(s) <= n else s[: n - 1] + '…'\n\n\ndef _approx_equal(a, b):\n    if isinstance(a, bool) or isinstance(b, bool):\n        return a == b\n    if isinstance(a, float) or isinstance(b, float):\n        try:\n            return math.isclose(a, b, rel_tol=1e-5, abs_tol=1e-6)\n        except TypeError:\n            return False\n    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):\n        return len(a) == len(b) and all(_approx_equal(x, y) for x, y in zip(a, b))\n    return a == b\n\n\nclass _Tracer:\n    def __init__(self, max_steps, base_names, out, trace_module):\n        self.max_steps = max_steps\n        self.base = base_names\n        self.out = out\n        self.trace_module = trace_module\n        self.steps = []\n        self.ids = {}\n        self.keep = []  # keep traced objects alive so id() values are never reused\n        self.pending = []\n\n    def sid(self, obj):\n        k = id(obj)\n        if k not in self.ids:\n            self.ids[k] = len(self.ids) + 1\n            self.keep.append(obj)\n        return self.ids[k]\n\n    def wanted(self, code):\n        if code.co_filename != '<solution>':\n            return False\n        if code.co_name == '<module>':\n            return self.trace_module\n        return bool(code.co_flags & _CO_OPTIMIZED) and not code.co_name.startswith('<')\n\n    def enc(self, v, depth=0):\n        t = type(v)\n        if v is None or t is bool or t is int or t is float or t is complex:\n            r = repr(v)\n            return ['n', r if len(r) <= 40 else r[:39] + '…']\n        if t is str:\n            return ['s', v if len(v) <= 120 else v[:119] + '…']\n        if depth > 3:\n            return ['o', _short(v, 30)]\n        if isinstance(v, (list, tuple, _deque, set, frozenset)):\n            if isinstance(v, list):\n                kind = 'l'\n            elif isinstance(v, tuple):\n                kind = 't'\n            elif isinstance(v, _deque):\n                kind = 'q'\n            else:\n                kind = 'S'\n            if kind == 'S':\n                try:\n                    items = sorted(v)\n                except TypeError:\n                    items = list(v)\n            else:\n                items = list(v)\n            res = [kind, self.sid(v), [self.enc(x, depth + 1) for x in items[:64]]]\n            if len(items) > 64:\n                res.append(len(items))\n            return res\n        if isinstance(v, dict):\n            items = list(v.items())\n            return ['d', self.sid(v), [[self.enc(k, depth + 1), self.enc(x, depth + 1)] for k, x in items[:48]], len(items), t.__name__]\n        if hasattr(v, '__dict__') and not isinstance(v, _SKIP) and not callable(v):\n            self.pending.append(v)\n            return ['r', self.sid(v)]\n        return ['o', _short(v, 60)]\n\n    def heap(self):\n        h = {}\n        while self.pending and len(h) < 160:\n            v = self.pending.pop(0)\n            k = self.sid(v)\n            if k in h:\n                continue\n            h[k] = None\n            d = vars(v)\n            if 'val' in d and 'next' in d and 'left' not in d:\n                rec = ['L', self.enc(d['val'], 2), self.enc(d['next'], 2)]\n                if 'random' in d:\n                    rec.append(self.enc(d['random'], 2))\n                h[k] = rec\n            elif 'val' in d and 'left' in d and 'right' in d:\n                rec = ['T', self.enc(d['val'], 2), self.enc(d['left'], 2), self.enc(d['right'], 2)]\n                if 'next' in d:\n                    rec.append(self.enc(d['next'], 2))\n                h[k] = rec\n            else:\n                attrs = [[a, self.enc(x, 1)] for a, x in list(d.items())[:16] if not a.startswith('__')]\n                h[k] = ['O', type(v).__name__, attrs]\n        self.pending = []\n        return {str(k): v for k, v in h.items() if v is not None}\n\n    def local_vars(self, fr):\n        is_mod = fr.f_code.co_name == '<module>'\n        out = []\n        for k, v in list(fr.f_locals.items()):\n            if k.startswith('__') or (is_mod and k in self.base):\n                continue\n            if isinstance(v, (types.ModuleType, type)) or callable(v):\n                continue\n            if k == 'self' and type(v).__name__ == 'Solution':\n                try:\n                    if not vars(v):\n                        continue\n                except TypeError:\n                    continue\n            out.append((k, v))\n        return out\n\n    def snapshot(self, frame, event, arg):\n        if len(self.steps) >= self.max_steps:\n            raise _StepLimit()\n        frames = []\n        f = frame\n        while f is not None:\n            if self.wanted(f.f_code):\n                frames.append(f)\n            f = f.f_back\n        frames.reverse()\n        self.pending = []\n        fr_out = []\n        for fr in frames:\n            fr_out.append({'n': fr.f_code.co_name, 'l': fr.f_lineno, 'v': [[k, self.enc(v)] for k, v in self.local_vars(fr)]})\n        st = {'e': event, 'l': frame.f_lineno, 'f': fr_out, 'o': len(self.out.getvalue())}\n        if event == 'return':\n            st['r'] = self.enc(arg)\n        elif event == 'exception':\n            et, ev = arg[0], arg[1]\n            st['x'] = et.__name__ + (': ' + str(ev) if str(ev) else '')\n        st['h'] = self.heap()\n        self.steps.append(st)\n\n    def dispatch(self, frame, event, arg):\n        if event == 'call' and self.wanted(frame.f_code):\n            self.snapshot(frame, 'call', None)\n            return self.local\n        return None\n\n    def local(self, frame, event, arg):\n        if event == 'line':\n            self.snapshot(frame, 'line', None)\n        elif event == 'return':\n            self.snapshot(frame, 'return', arg)\n        elif event == 'exception':\n            self.snapshot(frame, 'exception', arg)\n        return self.local\n\n\ndef _split(src, name):\n    tree = ast.parse(src, name)\n    last = None\n    if tree.body and isinstance(tree.body[-1], ast.Expr):\n        last = ast.Expression(tree.body.pop().value)\n    return compile(tree, name, 'exec'), (compile(last, name, 'eval') if last is not None else None)\n\n\ndef api_run(code, driver='', mode='run', max_steps=1200, expect=None):\n    \"\"\"Run `code`, then the `driver` snippet (its last expression is the result).\n    mode='trace' records every line executed in the solution. Returns JSON.\"\"\"\n    ns = {'__name__': '__main__', '__builtins__': builtins}\n    exec(_PRELUDE_CODE, ns)\n    base = set(ns)\n    out = io.StringIO()\n    res = {'ok': True, 'value': None, 'match': None}\n    tracer = None\n    old = sys.stdout\n    t0 = time.perf_counter()\n    has_driver = bool(driver and driver.strip())\n    try:\n        sys.stdout = out\n        d_exec = d_eval = None\n        if has_driver:\n            sol = compile(code, '<solution>', 'exec')\n            d_exec, d_eval = _split(driver, '<driver>')\n        else:\n            # no example call: behave like a REPL and show the value of a final expression\n            sol, d_eval = _split(code, '<solution>')\n        if mode == 'trace':\n            tracer = _Tracer(int(max_steps or 1200), base, out, trace_module=not has_driver)\n            sys.settrace(tracer.dispatch)\n        try:\n            exec(sol, ns)\n            if d_exec is not None:\n                exec(d_exec, ns)\n            val = eval(d_eval, ns) if d_eval is not None else None\n        finally:\n            sys.settrace(None)\n        if d_eval is not None and (has_driver or val is not None):\n            shown = ns['show'](val)\n            res['value'] = _short(shown, 4000)\n            if expect is not None and str(expect).strip() != '':\n                try:\n                    res['match'] = bool(_approx_equal(shown, eval(expect, ns)))\n                    res['expect'] = expect\n                except Exception:\n                    res['match'] = None\n    except _StepLimit:\n        res['ok'] = False\n        res['limit'] = True\n        res['error'] = 'Stopped after %d steps: the visualizer has a step limit. Try a smaller input.' % int(max_steps or 1200)\n    except SyntaxError as e:\n        res['ok'] = False\n        res['errline'] = e.lineno if e.filename == '<solution>' else None\n        res['error'] = 'SyntaxError: %s (line %s%s)' % (e.msg, e.lineno, '' if e.filename == '<solution>' else ' of the example call')\n    except BaseException as e:  # report every error to the learner, including KeyboardInterrupt-style ones\n        res['ok'] = False\n        tb, line = e.__traceback__, None\n        while tb is not None:\n            if tb.tb_frame.f_code.co_filename == '<solution>':\n                line = tb.tb_lineno\n            tb = tb.tb_next\n        res['errline'] = line\n        res['error'] = '%s: %s%s' % (type(e).__name__, e, ('  (line %d)' % line) if line else '')\n    finally:\n        sys.settrace(None)\n        sys.stdout = old\n    res['stdout'] = out.getvalue()[:20000]\n    res['ms'] = round((time.perf_counter() - t0) * 1000, 1)\n    if tracer is not None:\n        res['steps'] = tracer.steps\n    return json.dumps(res)\n";
